import * as T from './vendor/three.module.js';
import {TRACK,TRACK_LENGTH,trackAt,ROAD_HALF} from './kart-engine.js';
export class KartView{
 constructor(canvas,game,{renderer}={}){this.game=game;this.canvas=canvas;this.renderer=renderer??new T.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio||1,1.5));this.renderer.outputColorSpace=T.SRGBColorSpace;this.scene=new T.Scene();this.scene.fog=new T.Fog('#9ee6f0',95,245);this.camera=new T.PerspectiveCamera(65,1,.1,430);this.materials=[];this.textures=[];this.meshes=[];this.cameraReady=false;this.v=new T.Vector3();this.aim=new T.Vector3();this.frame=0;this.buildTrack();this.buildPickups();this.buildGates();this.resize();}
 async load(atlas=null){atlas??=await new T.TextureLoader().loadAsync('assets/kart-racers.webp');atlas.colorSpace=T.SRGBColorSpace;this.textures.push(atlas);this.cars=[];for(let i=0;i<6;i++){const tex=atlas.clone();tex.needsUpdate=true;tex.repeat.set(1/3,1/2);tex.offset.set(i%3/3,1-Math.floor(i/3)/2-.5);this.textures.push(tex);const material=new T.SpriteMaterial({map:tex,transparent:true,alphaTest:.08,depthWrite:false});this.materials.push(material);const car=new T.Sprite(material);car.scale.set(3.1,3.1,1);car.center.set(.5,0);this.scene.add(car);const shadow=new T.Mesh(new T.CircleGeometry(1.25,16),this.mat('#092949',{transparent:true,opacity:.28,depthWrite:false}));shadow.rotation.x=-Math.PI/2;this.scene.add(shadow);this.cars.push({car,shadow});}this.render(.016);}
 mat(color,more={}){const m=new T.MeshBasicMaterial({color,...more});this.materials.push(m);return m;}
 strip(inner,outer,palette,elevation=0){const positions=[],colors=[],color=new T.Color();for(let i=0;i<720;i++){const a=trackAt(TRACK[i].s),b=trackAt(TRACK[i+1].s);for(const sign of [-1,1]){const pts=[[a,inner],[a,outer],[b,outer],[a,inner],[b,outer],[b,inner]];color.set(palette[Math.floor(i/6)%palette.length]);for(const [p,w]of pts){positions.push(p.x+p.nx*w*sign,p.y+elevation,p.z+p.nz*w*sign);colors.push(color.r,color.g,color.b);}}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const m=new T.Mesh(geo,new T.MeshBasicMaterial({vertexColors:true,side:T.DoubleSide}));this.materials.push(m.material);this.scene.add(m);}
 at(obj,distance,lateral=0,height=0){const p=trackAt(distance);obj.position.set(p.x+p.nx*lateral,p.y+height,p.z+p.nz*lateral);return p;}

 orientSurface(obj,distance){const p=trackAt(distance),a=trackAt(distance-.25),b=trackAt(distance+.25),right=new T.Vector3(p.nx,0,p.nz),forward=new T.Vector3(p.tx,(b.y-a.y)/.5,p.tz).normalize(),up=new T.Vector3().crossVectors(right,forward).normalize();obj.quaternion.setFromRotationMatrix(new T.Matrix4().makeBasis(right,forward,up));}
 buildTrack(){this.strip(8.2,30,['#89d96d','#8fdd72']);this.strip(7,8.2,['#ff797c','#fff5cc']);this.strip(0,7,['#556e97','#526b92'],.02);this.strip(6.6,6.7,['#ffe997'],.09);
 const sea=new T.Mesh(new T.PlaneGeometry(1500,1500),this.mat('#54cadb'));sea.rotation.x=-Math.PI/2;sea.position.y=-3;this.scene.add(sea);
 // Track markings and start grid are functional race geometry.
 const dashGeo=new T.PlaneGeometry(.13,3),dashMat=this.mat('#e3f4ff',{side:T.DoubleSide}),dashes=new T.InstancedMesh(dashGeo,dashMat,Math.ceil(TRACK_LENGTH/13)*2),dummy=new T.Object3D();let index=0;for(let s=0;s<TRACK_LENGTH;s+=13){for(const lane of[-2.3,2.3]){const p=this.at(dummy,s,lane,.10);this.orientSurface(dummy,s);dummy.updateMatrix();dashes.setMatrixAt(index++,dummy.matrix);}}dashes.instanceMatrix.needsUpdate=true;this.scene.add(dashes);
 for(let x=0;x<10;x++)for(let z=0;z<3;z++){const tile=new T.Mesh(new T.PlaneGeometry(1.4,1.35),this.mat((x+z)%2?'#173257':'#ffffff',{side:T.DoubleSide}));const p=this.at(tile,2+z*1.35,-6.3+x*1.4,.10);this.orientSurface(tile,2+z*1.35);this.scene.add(tile);}
 this.boostRing=new T.Mesh(new T.RingGeometry(1.15,1.4,24),this.mat('#ffd64a',{side:T.DoubleSide,transparent:true,opacity:.8,depthWrite:false}));this.boostRing.rotation.x=-Math.PI/2;this.scene.add(this.boostRing);
 this.shieldRing=new T.Mesh(new T.SphereGeometry(1.85,16,10),this.mat('#56edff',{wireframe:true,transparent:true,opacity:.38,depthWrite:false}));this.scene.add(this.shieldRing);
 this.sparks=[];for(let i=0;i<10;i++){const spark=new T.Mesh(new T.OctahedronGeometry(.1),this.mat('#61dcff'));this.scene.add(spark);this.sparks.push(spark);}
 }
 label(text,color='#ffffff'){const c=document.createElement('canvas');c.width=256;c.height=128;const ctx=c.getContext('2d');ctx.font='900 64px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(text,128,64);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;this.textures.push(tex);const mat=new T.SpriteMaterial({map:tex,transparent:true,depthWrite:false});this.materials.push(mat);const sprite=new T.Sprite(mat);sprite.scale.set(7,3.5,1);return sprite;}
 buildPickups(){this.pickupMeshes=new Map();for(const p of this.game.pickups){let m;if(p.kind==='coin'){m=new T.Mesh(new T.OctahedronGeometry(.65),this.mat('#ffdc46'));this.at(m,p.distance,p.lateral,1.1);}else if(p.kind==='pad'){m=new T.Mesh(new T.PlaneGeometry(2.6,5),this.mat('#5ff5df',{side:T.DoubleSide}));const t=this.at(m,p.distance,p.lateral,.14);this.orientSurface(m,p.distance);const label=this.label('»','#003d68');this.at(label,p.distance,p.lateral,.5);label.scale.set(2.5,1.25,1);this.scene.add(label);m.userData.label=label;this.meshes.push(label);}else{m=new T.Mesh(new T.CircleGeometry(1.35,20),this.mat('#493075',{side:T.DoubleSide}));this.at(m,p.distance,p.lateral,.14);this.orientSurface(m,p.distance);const warn=this.label('!','#ffb8cc');this.at(warn,p.distance,p.lateral,.8);warn.scale.set(1.3,1.2,1);this.scene.add(warn);m.userData.label=warn;this.meshes.push(warn);}this.scene.add(m);this.pickupMeshes.set(p.id,m);}}
 buildGates(){this.gates=[];for(const s of [.2,.51,.82]){const d=TRACK_LENGTH*s,p=trackAt(d),group=new T.Group();group.position.set(p.x,p.y,p.z);group.rotation.y=p.heading;for(const x of[-7,7]){const post=new T.Mesh(new T.BoxGeometry(.5,6,.6),this.mat('#ffe372'));post.position.set(x,3,0);group.add(post);}const top=new T.Mesh(new T.BoxGeometry(14.5,.7,.7),this.mat('#b598ff'));top.position.y=6;group.add(top);const label=this.label('Aa','#ffffff');label.position.y=7;label.scale.set(5,2.5,1);group.add(label);this.scene.add(group);this.gates.push(group);}}
 resize(){const b=this.canvas.getBoundingClientRect();this.renderer.setSize(Math.max(1,b.width),Math.max(1,b.height),false);this.camera.aspect=Math.max(1,b.width)/Math.max(1,b.height);this.camera.updateProjectionMatrix();}
 setGame(game){this.game=game;this.cameraReady=false;for(const m of this.pickupMeshes.values())m.visible=true;}
 render(dt=.016){const g=this.game,p=trackAt(g.distance);this.frame+=dt;this.v.set(p.x+p.nx*g.lateral-p.tx*11,p.y+6.4,p.z+p.nz*g.lateral-p.tz*11);if(!this.cameraReady){this.camera.position.copy(this.v);this.cameraReady=true;}else this.camera.position.lerp(this.v,1-Math.exp(-dt*9));this.aim.set(p.x+p.nx*g.lateral+p.tx*18,p.y+1.2,p.z+p.nz*g.lateral+p.tz*18);this.camera.lookAt(this.aim);
 if(this.cars){const all=[{distance:g.distance,lateral:g.lateral},...g.ai];all.forEach((r,i)=>{const {car,shadow}=this.cars[i],t=this.at(car,r.distance,r.lateral,.18);this.at(shadow,r.distance,r.lateral,.10);this.orientSurface(shadow,r.distance);car.material.rotation=i===0?-g.steer*(g.drifting?.08:.04):Math.sin(g.time+r.id)*.025;const delta=Math.abs(r.distance-g.distance);car.visible=shadow.visible=i===0||delta<150;});}
 this.at(this.boostRing,g.distance,g.lateral,.12);this.orientSurface(this.boostRing,g.distance);this.boostRing.visible=g.boost>0;this.boostRing.scale.setScalar(1+Math.sin(g.time*18)*.08);this.at(this.shieldRing,g.distance,g.lateral,1.4);this.shieldRing.visible=g.shield>0;
 for(let i=0;i<this.sparks.length;i++){const m=this.sparks[i];m.visible=g.drift>.5||g.boost>0;const back=1.2+(i%5)*.45;this.at(m,g.distance-back,g.lateral+(i%2?1:-1)*(1+Math.sin(this.frame*20+i)*.15),.35+Math.sin(this.frame*25+i)*.2);m.material.color.set(g.boost>0?'#ffdf43':g.drift>=1.8?'#ff91de':'#66dfff');}
 // Only the closest lap's instances are visible, avoiding overlapping pickups on a closed circuit.
 for(const p of g.pickups){const m=this.pickupMeshes.get(p.id);m.visible=!p.taken&&p.distance>=g.distance-15&&p.distance<g.distance+170;if(m.userData.label)m.userData.label.visible=m.visible;if(p.kind==='coin'){m.rotation.y=this.frame*2;}}
 this.renderer.render(this.scene,this.camera);
 }
 dispose(){const geometries=new Set();this.scene.traverse(o=>{if(o.geometry)geometries.add(o.geometry);});for(const geo of geometries)geo.dispose();for(const m of new Set(this.materials))m.dispose();for(const t of new Set(this.textures))t.dispose();this.renderer.dispose();}
}
